<?php
declare(strict_types=1);
namespace App\Command;
use App\Imperium\Runtime\Authorship\AuthorshipCommissionAcceptanceService; use Symfony\Component\Console\Attribute\AsCommand; use Symfony\Component\Console\Command\Command; use Symfony\Component\Console\Input\InputArgument; use Symfony\Component\Console\Input\InputInterface; use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:studium:accept-commission',description:'Have the occupied Chancellor accept an exact authorship commission')]
final class StudiumAcceptCommissionCommand extends Command{public function __construct(private readonly AuthorshipCommissionAcceptanceService $service){parent::__construct();}protected function configure():void{$this->addArgument('commission-id',InputArgument::REQUIRED)->addArgument('binding-id',InputArgument::REQUIRED);}protected function execute(InputInterface $input,OutputInterface $output):int{try{$a=$this->service->accept('studium',(string)$input->getArgument('commission-id'),(string)$input->getArgument('binding-id'));}catch(\Throwable$e){$output->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$output->writeln('<info>STUDIUM_COMMISSION_ACCEPTED</info> '.$a['acceptance_id']);$output->writeln('Chancellor: '.$a['actor']['manifestation_id']);$output->writeln('Disposition: '.$a['disposition']);$output->writeln('Authorship authority: EXERCISABLE FOR EXACT COMMISSION');$output->writeln('Subordinate Notary resolution: REQUIRED');$output->writeln('Spawning authority: NOT GRANTED');$output->writeln('Execution authority: NOT GRANTED');return self::SUCCESS;}}
